const deepCopy = (type) => {
    const pushArray = (input, key) => {
        let arrOut = [];
        for (let i = 0; i < input.length; i++) {
            switch (typeof input[i]) {
                case 'object':
                    if (Array.isArray(input[i])) arrOut.push(pushArray(input[i]));
                    else {
                        if (key == "TYPE") arrOut.push(input[i]);
                        else arrOut.push(deepCopy(input[i]));
                    }
                    break;
                default:
                    arrOut.push(input[i]);
                    break;
            }
        }
        return arrOut;
    };
    let output = JSON.parse(JSON.stringify(type));
    if (Array.isArray(type)) output = pushArray(type);
    else {
        for (let key in type) {
            switch (typeof type[key]) {
                case 'object':
                    if (Array.isArray(type[key])) output[key] = pushArray(type[key], key);
                    else {
                        if (key == "TYPE") output[key] = type[key];
                        else output[key] = deepCopy(type[key]);
                    }
                    break;
                default:
                    output[key] = type[key];
                    break;
            }
        }
    }
    return output;
};
let customCounters = {};
const makeExportName = (type, append, stats = []) => {
    let out;

    for (let entity in exports) {
        if (exports[entity] == type) out = entity;
    }

    if (out == undefined) {
        if (customCounters[append] == undefined) customCounters[append] = 0;
        return `custom${append}${customCounters[append]++}`;
    }

    out += append;
    
    for (let starArr of stats) {
        for (let numb of starArr) {
            out += `${numb}`.replaceAll('.', 'o').replaceAll(',', 'l');
        }
    }
    
    return out;
};
const newExport = (name) => { // replace all instances with makeExportName
    name = name.replace(/[^a-z0-9]/gi,'');
    for (i = 0; exports[name + (i || '')] != undefined; i++) {}
    if (i) name += i;
    return name;
};
const applyStats = (guns, stats, options = {}) => {
    if (guns) {
        for (let gun of guns) {
            if (gun.PROPERTIES) {
                if (options.propertyEdit) options.propertyEdit(gun.PROPERTIES);
                if (gun.PROPERTIES.SHOOT_SETTINGS) {
                    if (options.shootEdit) options.shootEdit(gun.PROPERTIES);
                    gun.PROPERTIES.SHOOT_SETTINGS = combineStats([Object.values(gun.PROPERTIES.SHOOT_SETTINGS), ...stats]);
                }
            }
        }
    }
};
const createTurret = (type, stats = [g.blank], syncTurretSkills = true) => {
    let output = deepCopy(type);
    output.LABEL = 'Turret';
    output.DANGER = 0;
    output.CONTROLLERS = ["canRepel", "mapAltToFire", "nearestDifferentMaster", "onlyAcceptInArc"];
    applyStats(output.GUNS, [g.turret, ...stats]);
    output.SYNC_SKILLS = output.SYNC_TURRET_SKILLS = output.SYNCS_SKILLS = syncTurretSkills;
    return output;
};
const createTurretBoss = (type, stats = [g.blank], syncTurretSkills = true) => {
    return createTurret(type, [[1, 0, 1, 1.176, 1.667, 1.667, 1.667, 1.111, 1.176, 1, 10, 1, 1], ...stats], syncTurretSkills);
};
const makeIron = (type, name, options = {}) => {
    let output = deepCopy(type);
    output.ABILITY_IMMUNE = true;
    if (options.prop || false) {
        let props = makeShell({
            color: options.color || 16, // 209
            shape: -8,
            size: 1.1
        });
        output.PROPS = output.PROPS == null ? [props] : [props, ...output.PROPS]; 
    } else {
        if (output.TURRETS !== undefined) {
            for (let i = 0; i < output.TURRETS.length; i++) {
                output.TURRETS[i].TYPE = [output.TURRETS[i].TYPE, {
                    COLOR: options.color || 209
                }];
            }
        } else if (output.PROPS !== undefined) {
            for (let i = 0; i < output.PROPS.length; i++) {
                output.PROPS[i].COLOR = options.color || 209;
            }
        }
    }
    output.LABEL = name || 'Kevlar ' + output.LABEL;
	output.UPGRADES_TIER_1 = [];
	output.UPGRADES_TIER_2 = [];
	output.UPGRADES_TIER_3 = [];
	output.UPGRADES_TIER_4 = [];
    return output;
};
const makeAuto = (type, name, options = {}) => {
    let output = deepCopy(type);
    output.LABEL = name || 'Auto-' + type.LABEL;
    if (output.DANGER < 7) output.DANGER++;
    output.TURRETS = output.TURRETS || [];
    options = {
        size: options.size == undefined ? 10 : options.size,
        x: options.x == undefined ? 0 : options.x,
        angle: options.angle == undefined ? 180 : options.angle,
        rot: options.rot == undefined ? 361 : options.rot,
        layer: options.layer == undefined ? 1 : options.layer,
        type: options.type == undefined ? exports.autoTurret : options.type,
        independent: options.independent == undefined ? true : options.independent,
        color: options.color == undefined ? 16 : options.color
    };
    output.TURRETS.push({
        POSITION: [options.size, options.x, 0, options.angle, options.rot, options.layer],
        TYPE: [options.type, {
            CONTROLLERS: ['nearestDifferentMaster'],
            INDEPENDENT: options.independent,
            COLOR: options.color,
            AI: {
                SKYNET: true
            }
        }]
    });
    return output;
};
if (!global.structuredClone) global.structuredClone = obj => JSON.parse(JSON.stringify(obj));
const makeAnimTank = (exportName, name, frame1, frame31, options = {}) => {
    let duration = options.duration || 20;
    let prop = options.prop != null ? options.prop : true;
    let gunPositionA = options.gunPositionA || false;   
    let gunPositionB = options.gunPositionB || false;
    let turretPositionA = options.turretPositionA || false;
    let turretPositionB = options.turretPositionB || false;
    options.gunProps = options.gunProps || [];
    exports[`${exportName}0`] = structuredClone(frame1);
    exports[`${exportName}0`].GUNS = structuredClone(frame1.GUNS || []);
    exports[`${exportName}0`].TURRETS = frame1.TURRETS || [];
    exports[`${exportName}0`].LABEL = name;
    exports[`${exportName}31`] = structuredClone(frame31);
    exports[`${exportName}31`].GUNS = structuredClone(frame31.GUNS || []);
    exports[`${exportName}31`].TURRETS = frame31.TURRETS || [];
    exports[`${exportName}31`].LABEL = name;
    exports[`${exportName}0`].IS_USED = exports[`${exportName}31`].IS_USED = true;
    if (frame1.GUNS) for (let i = 0; i < frame1.GUNS.length; i++) {
        if (frame1.GUNS[i].PROPERTIES != undefined) {
            if (frame1.GUNS[i].PROPERTIES.TYPE != undefined) {
                exports[`${exportName}0`].GUNS[i].PROPERTIES.TYPE = frame1.GUNS[i].PROPERTIES.TYPE;
            }
        }
    }
    
    if (frame31.GUNS) for (let i = 0; i < frame31.GUNS.length; i++) {
        if (frame31.GUNS[i].PROPERTIES != undefined) {
            if (frame31.GUNS[i].PROPERTIES.TYPE != undefined) {
                exports[`${exportName}31`].GUNS[i].PROPERTIES.TYPE = frame31.GUNS[i].PROPERTIES.TYPE;
            }
        }
    }

    let gunsA = exports[`${exportName}0`].GUNS;
    let gunsB = exports[`${exportName}31`].GUNS;
    let turretsA = exports[`${exportName}0`].TURRETS;
    let turretsB = exports[`${exportName}31`].TURRETS;
    for (let i = 1; i < 31; i++) {
        exports[`${exportName}${i}`] = {
            PARENT: [exports.genericTank],
            LABEL: name,
            GUNS: [],
            TURRETS: []
        }
        for (let j = 0; j < Math.max(gunsA.length, gunsB.length); j++) {
            if (j < Math.min(gunsA.length, gunsB.length)) {
                exports[`${exportName}${i}`].GUNS.push({
                    POSITION: [
                        gunsA[j].POSITION[0] * (1 - i / 31) + gunsB[j].POSITION[0] * (i / 31),
                        gunsA[j].POSITION[1] * (1 - i / 31) + gunsB[j].POSITION[1] * (i / 31),
                        gunsA[j].POSITION[2] * (1 - i / 31) + gunsB[j].POSITION[2] * (i / 31),
                        gunsA[j].POSITION[3] * (1 - i / 31) + gunsB[j].POSITION[3] * (i / 31),
                        gunsA[j].POSITION[4] * (1 - i / 31) + gunsB[j].POSITION[4] * (i / 31),
                        gunsA[j].POSITION[5] * (1 - i / 31) + gunsB[j].POSITION[5] * (i / 31),
                        0
                    ],
                    PROPERTIES: {
                        SKIN: gunsA[j].PROPERTIES ? gunsA[j].PROPERTIES.SKIN || null : null,
                        COLOR: options.gunProps.includes(j) ? 245 + i : gunsA[j].PROPERTIES ? gunsA[j].PROPERTIES.COLOR || null : null,
                        COLOR_UNMIX: gunsA[j].PROPERTIES ? gunsA[j].PROPERTIES.COLOR_UNMIX || null : null
                    }
                });
            } else if (gunsA.length > gunsB.length) {
                exports[`${exportName}${i}`].GUNS.push({
                    POSITION: [
                        gunsA[j].POSITION[0] * (1 - i / 31),
                        gunsA[j].POSITION[1] * (1 - i / 31),
                        gunsA[j].POSITION[2] * (1 - i / 31),
                        gunsA[j].POSITION[3] * (1 - i / 31),
                        gunsA[j].POSITION[4] * (1 - i / 31),
                        gunsA[j].POSITION[5],
                        0
                    ],
                    PROPERTIES: {
                        SKIN: gunsA[j].PROPERTIES ? gunsA[j].PROPERTIES.SKIN || null : null,
                        COLOR: options.gunProps.includes(j) ? 245 + i : gunsA[j].PROPERTIES ? gunsA[j].PROPERTIES.COLOR || null : null,
                        COLOR_UNMIX: gunsA[j].PROPERTIES ? gunsA[j].PROPERTIES.COLOR_UNMIX || null : null
                    }
                });
            } else {
                exports[`${exportName}${i}`].GUNS.push({
                    POSITION: [
                        gunsB[j].POSITION[0] * (i / 31),
                        gunsB[j].POSITION[1] * (i / 31),
                        gunsB[j].POSITION[2] * (i / 31),
                        gunsB[j].POSITION[3] * (i / 31),
                        gunsB[j].POSITION[4] * (i / 31),
                        gunsB[j].POSITION[5],
                        0
                    ],
                    PROPERTIES: {
                        SKIN: gunsB[j].PROPERTIES ? gunsB[j].PROPERTIES.SKIN || null : null,
                        COLOR: options.gunProps.includes(j) ? 245 + i : gunsB[j].PROPERTIES ? gunsB[j].PROPERTIES.COLOR || null : null,
                        COLOR_UNMIX: gunsB[j].PROPERTIES ? gunsB[j].PROPERTIES.COLOR_UNMIX || null : null
                    }
                });
            }
        }
        if (prop) exports[`${exportName}${i}`].GUNS.push({
            POSITION: [14, 3.5, 1, 0, 0, 0, 0],
            PROPERTIES: {
                COLOR: 245 + i
            }
        });
        let posA = turretPositionA ? turretPositionA : turretsA;
        let posB = turretPositionB ? turretPositionB : turretsB;
        for (let j = 0; j < Math.max(posA.length, posB.length); j++) {
            if (j < Math.min(posA.length, posB.length)) {
                exports[`${exportName}${i}`].TURRETS.push({
                    POSITION: [
                        posA[j].POSITION[0] * (1 - i / 31) + posB[j].POSITION[0] * (i / 31),
                        posA[j].POSITION[1] * (1 - i / 31) + posB[j].POSITION[1] * (i / 31),
                        posA[j].POSITION[2] * (1 - i / 31) + posB[j].POSITION[2] * (i / 31),
                        posA[j].POSITION[3] * (1 - i / 31) + posB[j].POSITION[3] * (i / 31),
                        0,
                        posA[j].POSITION[5]
                    ],
                    TYPE: [posA[j].TYPE, {
                        INDEPENDENT: true,
                        CONTROLLERS: []
                    }]
                });
            } else if (posA.length > posB.length) {
                exports[`${exportName}${i}`].TURRETS.push({
                    POSITION: [
                        posA[j].POSITION[0] * (1 - i / 31),
                        posA[j].POSITION[1] * (1 - i / 31),
                        posA[j].POSITION[2] * (1 - i / 31),
                        posA[j].POSITION[3] * (1 - i / 31),
                        0,
                        posA[j].POSITION[5]
                    ],
                    TYPE: [posA[j].TYPE, {
                        INDEPENDENT: true,
                        CONTROLLERS: []
                    }]
                });
            } else {
                exports[`${exportName}${i}`].TURRETS.push({
                    POSITION: [
                        posB[j].POSITION[0] * (i / 31),
                        posB[j].POSITION[1] * (i / 31),
                        posB[j].POSITION[2] * (i / 31),
                        posB[j].POSITION[3] * (i / 31),
                        0,
                        posB[j].POSITION[5]
                    ],
                    TYPE: [posB[j].TYPE, {
                        INDEPENDENT: true,
                        CONTROLLERS: []
                    }]
                });
            }
        }
    }
    if (prop) {
        exports[`${exportName}0`].GUNS.push({
            POSITION: [14, 3.5, 1, 0, 0, 0, 0],
            PROPERTIES: {
                COLOR: 245
            }
        });
        exports[`${exportName}31`].GUNS.push({
            POSITION: [14, 3.5, 1, 0, 0, 0, 0],
            PROPERTIES: {
                COLOR: 276
            }
        });
    }
    exports[`${exportName}0`].ON_ALT = (me, entities) => {
        animate(me, exportName, 31, duration, true, 0, entities);
    };
    exports[`${exportName}31`].ON_ALT = (me, entities) => {
        animate(me, exportName, 31, duration, false, 0, entities);
    }
}
