const makeFlank = (type, sides = 3, name, options = {}) => {
    let output = deepCopy(type),
        reloadDelay = options.reload_delay || new Array(sides),
        stats = options.stats || [g.blank],
        angles = options.angles || new Array(sides);
    
    applyStats(output.GUNS, [g.flank, ...stats]);

    let baseGuns = deepCopy(output.GUNS);
    output.GUNS = [];
    for (let i = 0; i < sides; i++) {
        for (let j = 0; j < baseGuns.length; j++) {
            let outputGun = deepCopy(baseGuns[j]);
            outputGun.POSITION[5] += angles[i] == undefined ? 360 / sides * i : angles[i];
            if (reloadDelay[i] != undefined) outputGun.POSITION[6] += reloadDelay[i];
            output.GUNS.push(outputGun);
        }
    }
    if (output.DANGER < 7) output.DANGER++;
    output.LABEL = name || `Flank ${output.LABEL}`;
    return output;
};
const makePara = (x, yy, name, options = {}) => {
    if (options.c == null) options.c = 50;
    if (options.mul == null) options.mul = 2;
    if (options.cycle == null) options.cycle = 360;
    if (options.stat == null) options.stat = g.blank;
    let bullet = deepCopy(exports.bullet);
    bullet.GUNS = [];
    bullet.MOTION_TYPE = 'stopOnDeath';
    for (let i = 0; i < options.cycle; i += options.cycle / options.c) {
        let ex = eval(x),
            ey = eval(yy),
            spd = Math.hypot(ex, ey) * options.mul;
        bullet.GUNS.push({
            POSITION: [0, 18, 1, 10, 0, Math.atan2(ey, ex) * (180 / Math.PI), 1e99],
            PROPERTIES: {
                SHOOT_SETTINGS: combineStats([
                    [66, 1, .0000001, .25, 1, .07, 5, spd, spd, 2, 1, .0000001, 1], options.stat
                ]),
                TYPE: [exports.bullet, {
                    PERSISTS_AFTER_DEATH: true
                }],
                LABEL: gunCalcNames.thruster,
                SHOOT_ON_DEATH: true
            }
        })
    };
    return {
        PARENT: [exports.genericTank],
        LABEL: name || 'Parametric',
        GUNS: [{
            POSITION: [18, 8, 1, 0, 0, 0, 0],
            PROPERTIES: {
                SHOOT_SETTINGS: combineStats([
                    [66, 0, .1, 1, .0002, .2, 1, .000045, 2, 0, 1, 15, 1]
                ]),
                TYPE: bullet
            }
        }, {
            POSITION: [19, 3, 1, 0, 0, 0, 0],
            PROPERTIES: {
                COLOR: options.color || 25
            }
        }]
    };
};
